#define PI 3.14159265359
#define INV_PI 0.31830988618
#define INV_TWO_PI 0.15915494309

#define MAX_DIST 100.
#define SURF_DIST .001
#define EPS .0001
#define PI2 6.28
#define saturate(a) clamp(a,0.,1.)
#define S(a,b,t) smoothstep(a,b,t)
#define TS(a,b,c,d,t) smoothstep(a,b,t) * smoothstep(d,c,t)
#define REP(p,r) mod(p,r) - r * .5  

#define NORMALIZED_PHONG_POWER ROUGHNESS * 128.0
#define NORMALIZED_BLINN_PHONG_POWER ROUGHNESS * 1000.0

// 0: normalized lambert
// 1: disney
// 2: normalized disney
// 3: oren nayer
#define DIFFUSE_BRDF 1

// 0: normalized phong
// 1: normalized blinn phong
// 2: cook trance
#define SPECULAR_BRDF 2

// 0: directional light
// 1: point light
// 2: spot light
#define LIGHT_TYPE 0

#define ALBEDO vec3(.1, .4, .85)
#define EMISSIVE vec3(.002, .006, .009)
#define ROUGHNESS .5
#define METALLIC 1.
#define EMISSION vec3(.1, .4, .8) * 3.

#define BG_COLOR ALBEDO * .3

#define LIGHT_DIR vec3(-1., 1., -1.)
#define LIGHT_COLOR vec3(1.)


precision highp float;

// ---------------------------------------------------------------
// utilities
// ---------------------------------------------------------------

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

vec2 pmod(vec2 p, float s) {
    float a = PI / s - atan(p.x, p.y);
    float n = PI2 / s;
    a = floor(a / n) * n;
    p *= rot(-a);
    return p;
}

// ref: http://blog.hvidtfeldts.net/index.php/2011/08/distance-estimated-3d-fractals-iii-folding-space/
vec3 pmodn(vec3 p, vec3 n) {
    return p - 2. * min(0., dot(p, n)) * n;
}

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
}

float sdRoundBox(vec3 p, vec3 b, float r)
{
    vec3 q = abs(p) - b + r;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.) - r;
}

float sdTorus( vec3 p, vec2 t )
{
    vec2 q = vec2(length(p.xz)-t.x,p.y);
    return length(q)-t.y;
}

float opUnion(float d1, float d2) {
    return min(d1, d2);
}

vec2 opUnion2(vec2 a, vec2 b) {
	return a.x < b.x ? a : b;
}

// d2 から d1 を引く
float opSub(float d1, float d2) {
    return max(-d1, d2);
}

float opSmooth(float d1, float d2, float k)
{
    float h = clamp(.5 + .5 *(d2 - d1) / k, 0., 1.);
    return mix(d2, d1, h) - k * h * (1. - h);
}

float opSmoothSub(float d1, float d2, float k)
{
    float h = clamp(.5 - .5 * (d2 + d1) / k, 0., 1.);
    return mix(d2, -d1, h) + k * h * (1. - h);
}

// ---------------------------------------------------------------
// geometry, surface
// ---------------------------------------------------------------

struct Geometry {
	vec3 position;
    vec3 normal;
    vec3 viewDir;
};

struct Material {
	vec3 diffuseColor;
    vec3 specularColor;
    float specularRoughness;
};

struct IncidentLight {
	vec3 direction;
    vec3 color;
    bool visible;
};

struct DirectionalLight {
	vec3 direction;
    vec3 color;
};

struct PointLight {
    vec3 position;
    vec3 color;
    float dist;
    float decay;
};

struct SpotLight {
    vec3 position;
    vec3 direction;
    vec3 color;
    float dist;
    float decay;
    float coneCos;
    float penumbraCos;
};

struct ReflectedLight {
    vec3 directDiffuse;
    vec3 directSpecular;
};


//-------------------------------------------------------------------------------------------
// brdf
//-------------------------------------------------------------------------------------------

float SchlickFresnel(float u, float f0, float f90) {
    return f0 + (f90 - f0) * pow(1. - u, 5.);
}

vec3 diffuseNormalizedLambertBrdf(vec3 diffuseColor) {
	return diffuseColor / PI;
}

vec3 diffuseDisneyBrdf(IncidentLight incidentLight, Geometry geometry, vec3 diffuseColor, float specularRoughness) {
	vec3 N = geometry.normal;
    vec3 V = geometry.viewDir;
    vec3 L = incidentLight.direction;

    vec3 H = normalize(L + V);
    float dotLH = saturate(dot(L, H));
    float dotNL = saturate(dot(N, L));
    float dotNV = saturate(dot(N, V));
    float fd90 = .5 + 2. * dotLH * dotLH * specularRoughness;
    float FL = SchlickFresnel(1., fd90, dotNL);
    float FV = SchlickFresnel(1., fd90, dotNV);
    return (diffuseColor * FL * FV) / PI;
}

vec3 diffuseNormalizedDisneyBrdf(IncidentLight incidentLight, Geometry geometry, vec3 diffuseColor, float specularRoughness) {
	vec3 N = geometry.normal;
    vec3 V = geometry.viewDir;
    vec3 L = incidentLight.direction;

    vec3 H = normalize(L + V);
    float dotLH = saturate(dot(L, H));
    float dotNL = saturate(dot(N, L));
    float dotNV = saturate(dot(N, V));	

    float energyBias = mix(0., .5, specularRoughness);
    float energyFactor = mix(1., 1. / 1.51, specularRoughness);
    float fd90 = energyBias + 2. * dotLH * dotLH * specularRoughness;
    float FL = SchlickFresnel(1., fd90, dotNL);
    float FV = SchlickFresnel(1., fd90, dotNV);
    return (diffuseColor * FL * FV * energyFactor) / PI;
}

vec3 diffuseOrenNayerBrdf(IncidentLight incidentLight, Geometry geometry, vec3 diffuseColor, float specularRoughness) {
	vec3 N = geometry.normal;
    vec3 V = geometry.viewDir;
    vec3 L = incidentLight.direction;

    float dotNV = saturate(dot(N, V));
    float dotNL = saturate(dot(N, L));

    float roughness2 = specularRoughness * specularRoughness;
    float a = 1. - .5 * roughness2 / (roughness2 + .33);
    float b = .45 * roughness2 /(roughness2 + .09);
    float cosPhi = dot(
        normalize(V - dotNV * N),
        normalize(L - dotNL * N)
    );
    float sinNV = sqrt(1. - dotNV * dotNV);
    float sinNL = sqrt(1. - dotNL * dotNL);
    float s = dotNV < dotNL ? sinNV : sinNL;
    float t = dotNV > dotNL ? sinNV / dotNV : sinNL / dotNL;
    return diffuseColor * INV_PI * (a + b * cosPhi * s * t);
}

vec3 specularNormalizedPhongBrdf(vec3 specularColor, float dotRL, float power) {
	float norm = (power + 1.) / (PI * 2.);
    return specularColor * pow(dotRL, power) * norm;
}

vec3 specularNormalizedBlinnPhongBrdf(vec3 specularColor, float dotNH, float power) {
	float norm = (power + 2.) / (PI * 2.);
    return specularColor * pow(dotNH, power) * norm;
}

vec3 F_Schlick(vec3 specularColor, vec3 H, vec3 V) {
	return (specularColor + (1. - specularColor) * pow(1. - saturate(dot(V, H)),  5.));
}

float D_GGX(float a, float dotNH) {
    float a2 = a * a;
    float dotNH2 = dotNH * dotNH;
    float d = dotNH2 * (a2 - 1.) + 1.;
    return a2 / (PI * d * d);
}

float G_SmithSchlickGGX(float a, float dotNV, float dotNL) {
	float k = a * a * .5 + EPS;
    float gl = dotNL / (dotNL * (1. - k) + k);
    float gv = dotNV / (dotNV * (1. - k) + k);
    return gl * gv;
}

vec3 specularCookTranceBrdf(IncidentLight incidentLight, Geometry geometry, vec3 specularColor, float roughnessFactor) {
	vec3 N = geometry.normal;
    vec3 V = geometry.viewDir;
    vec3 L = incidentLight.direction;
    vec3 H = normalize(L + V);

    float dotNL = saturate(dot(N, L));
    float dotNV = saturate(dot(N, V));
    float dotNH = saturate(dot(N, H));
    float dotVH = saturate(dot(V, H));
    float dotLV= saturate(dot(L, V));
    float a = roughnessFactor * roughnessFactor;

    float D = D_GGX(a, dotNH);
    float G = G_SmithSchlickGGX(a, dotNV, dotNL);
    vec3 F = F_Schlick(specularColor, V, H);

    return (F * (G * D)) / (4. * dotNL * dotNV + EPS);
}

// rendering equation
void RE_Direct(IncidentLight incidentLight, Geometry geometry, Material material, inout ReflectedLight reflectedLight) {   
	vec3 N = geometry.normal;
    vec3 V = geometry.viewDir;
    vec3 L = incidentLight.direction;
    vec3 R = reflect(-geometry.viewDir, geometry.normal);

    float dotRL = saturate(dot(R, L));
    float dotNL = saturate(dot(N, L));
    float dotNV = saturate(dot(N, V));
    vec3 H = normalize(L + V);
    float dotNH = saturate(dot(N, H));
    float dotVH = saturate(dot(V, H));
    float dotLV= saturate(dot(L, V));    

    vec3 irradiance = dotNL * incidentLight.color;

    // adjust puctual light
    irradiance *= PI;

    vec3 diffuse = vec3(0.);
	vec3 specular = vec3(0.);

    #if DIFFUSE_BRDF == 0
    diffuse = diffuseNormalizedLambertBrdf(
        material.diffuseColor
    );
    #elif DIFFUSE_BRDF == 1
    diffuse = diffuseDisneyBrdf(
        incidentLight,
        geometry,
        material.diffuseColor,
        material.specularRoughness
    );
    #elif DIFFUSE_BRDF == 2
    diffuse = diffuseNormalizedDisneyBrdf(
        incidentLight,
        geometry,
        material.diffuseColor,
        material.specularRoughness
    );    
    #elif DIFFUSE_BRDF == 3
    diffuse = diffuseOrenNayerBrdf(
        incidentLight,
        geometry,
        material.diffuseColor,
        material.specularRoughness
    );    
    #endif

    #if SPECULAR_BRDF == 0
    specular = specularNormalizedPhongBrdf(
        material.specularColor,
        dotRL,
        NORMALIZED_PHONG_POWER
    );
    #elif SPECULAR_BRDF == 1
	specular = specularNormalizedBlinnPhongBrdf(
        material.specularColor,
        dotNH,
        NORMALIZED_BLINN_PHONG_POWER
	);    
    #elif SPECULAR_BRDF == 2
    specular = specularCookTranceBrdf(
        incidentLight,
        geometry,
        material.specularColor,
        material.specularRoughness
    );
    #endif

    reflectedLight.directDiffuse += irradiance * diffuse;;
    reflectedLight.directSpecular += irradiance * specular;
}

bool testLightInRange(float lightDistance, float cutoffDistance) {
	return any(bvec2(cutoffDistance == 0., lightDistance < cutoffDistance));
}

float punctualLightIntensityToIrradianceFactor(float lightDistance, float cutoffDistance, float decayExponent) {
    if(decayExponent > 0.) {
    	return pow(saturate(-lightDistance / cutoffDistance + 1.), decayExponent);
    }
    return 1.;
}

void setDirectionalDirectLightIrradiance(DirectionalLight directionalLight, Geometry geometry, out IncidentLight incidentLight) {
	incidentLight.color = directionalLight.color;
    incidentLight.direction = directionalLight.direction;
    incidentLight.visible = true;
}

void setPointDirectLightIrradiance(PointLight pointLight, Geometry geometry, out IncidentLight incidentLight) {
	vec3 L = pointLight.position - geometry.position;
    incidentLight.direction = normalize(L);

    float lightDistance = length(L);
    if(testLightInRange(lightDistance, pointLight.dist)) {
    	incidentLight.color = pointLight.color;
        incidentLight.color *= punctualLightIntensityToIrradianceFactor(lightDistance, pointLight.dist, pointLight.decay);
    	incidentLight.visible = true;
    } else {
    	incidentLight.color = vec3(0.);
        incidentLight.visible = false;
    }
}

void setSpotDirectLightIrradiance(SpotLight spotLight, Geometry geometry, out IncidentLight incidentLight) {
	vec3 L = spotLight.position - geometry.position;
    incidentLight.direction = normalize(L);

    float lightDistance = length(L);
    float angleCos = dot(incidentLight.direction, -spotLight.direction);

    if(all(bvec2(angleCos > spotLight.coneCos, testLightInRange(lightDistance, spotLight.dist)))) {
		float spotEffect = smoothstep(spotLight.coneCos, spotLight.penumbraCos, angleCos);
        incidentLight.color = spotLight.color;
        incidentLight.color *= spotEffect * punctualLightIntensityToIrradianceFactor(lightDistance, spotLight.dist, spotLight.decay);
        incidentLight.visible = true;
    } else {
    	incidentLight.color = vec3(0.);
        incidentLight.visible = false;        
    }
}

vec4 lighting(Geometry geometry, Material material) {
    // out going
    ReflectedLight reflectedLight = ReflectedLight(vec3(0.), vec3(0.));

    IncidentLight incidentLight;

    DirectionalLight directionalLight;
    directionalLight.direction = normalize(LIGHT_DIR);
    directionalLight.color = LIGHT_COLOR;

    PointLight pointLight;
    pointLight.position = LIGHT_DIR;
    pointLight.color = LIGHT_COLOR;
    pointLight.dist = 8.;
    pointLight.decay = 2.;

    SpotLight spotLight;
    spotLight.position = LIGHT_DIR;
    spotLight.direction = vec3(0.) - spotLight.position;
    spotLight.color = LIGHT_COLOR;
    spotLight.dist = 10.;
    spotLight.decay = 2.;
    spotLight.coneCos = PI / 3.;
    spotLight.penumbraCos = PI / 2.5;

    #if LIGHT_TYPE == 0
    setDirectionalDirectLightIrradiance(directionalLight, geometry, incidentLight);
    #elif LIGHT_TYPE == 1
    setPointDirectLightIrradiance(pointLight, geometry, incidentLight);
    #elif LIGHT_TYPE == 2
    setSpotDirectLightIrradiance(spotLight, geometry, incidentLight);
    #endif
    if(incidentLight.visible) {
    	RE_Direct(incidentLight, geometry, material, reflectedLight);
    }

    vec3 color = EMISSIVE
        + reflectedLight.directDiffuse
        + reflectedLight.directSpecular;

    return vec4(color, 1.);
}

// ---------------------------------------------------------------
// scene
// ---------------------------------------------------------------

vec2 scene(vec3 p) {
    vec2 res = vec2(100000., -1.);
    float t = iTime;

    vec3 q = p;

    q.xy *= rot(q.z * .12 + t * .01);

    q.z -= t * -6.;

    vec3 qs = q;

    q = REP(q, 6.);

    float d = 1000000.;

    float thin = .8;

    d = opSmooth(d, sdBox(q, vec3(20., thin, thin)) - .1, .2); // x
    d = opSmooth(d, sdBox(q, vec3(thin, 20., thin)) - .1, .2); // y 
    d = opSmooth(d, sdBox(q, vec3(thin, thin, 20.)) - .1, .2); // z 

    d += (sin(p.x + t * 4.) + cos(p.y + t * 2.) + sin(p.z + t * 4.)) * .2;

    p.z -= t * -1.6;
    p.xy *= rot(p.z * .08 + t *.2);
    qs = REP(p, .6);

    float thins = .18 + sin(t * 4.) * .05;

    d = opSmoothSub(sdBox(qs, vec3(thins, thins, thins)) - .1, d, .2); // x
    d = opSmoothSub(sdBox(qs, vec3(thins, thins, thins)) - .1, d, .2); // y 
    d = opSmoothSub(sdBox(qs, vec3(thins, thins, thins)) - .1, d, .2); // z 

    q.xy = pmod(q.xy, 4.);

    q.y -= .8;

    for(float i = 0.; i < 4.; i++) {
        q.y -= i * .2 + sin(t + i) * .1;
        q.xz *= rot(.45 + i * .2 + t);
        q -= vec3(sin(0.), sin(t + i * 10.), cos(t + i * 20.));

        d = opSmooth(
            d,
            sdBox(q, vec3(.2, .4, .8)) - .15, 
            .5
        );       
    }

    res = vec2(d, 0.);

    return res;
}


vec3 getNormal(vec3 p) {
	vec2 e = vec2(1., -1.) * EPS;
    return normalize(
        e.xyy * scene(p + e.xyy).x+
        e.yxy * scene(p + e.yxy).x+
        e.yyx * scene(p + e.yyx).x+
        e.xxx * scene(p + e.xxx).x
    );
}

vec2 raymarch(vec3 ro, vec3 rd, float side, inout vec3 emission) {
    float accDist = 0.;    
    float mat = 0.;

    for(int i = 0; i < 99; i++) {
        vec3 p = ro + rd * accDist;
        vec2 result = scene(p);
        float dist = result.x * side;
        // mat = result.y;
        if(abs(dist) < SURF_DIST || accDist > MAX_DIST) {
            break;
        }
        dist *= .75; // opt
        accDist += dist;                
        // emission += exp(abs(dist) * -300.);
        float ep = pow(sin(p.z * .6 + iTime * 6.) * .5 + .5, 4.);
        emission += (.001 + ep * .01) / pow(abs(dist), .8);
    }

    return vec2(accDist, mat);
}

// front -z
vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 forward = normalize(l - p);
    vec3 right = normalize(cross(vec3(0., 1., 0.), forward));
    vec3 up = normalize(cross(forward, right));

    return normalize(right * uv.x + up * uv.y + forward * z);        
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime;

    vec2 uv = (fragCoord.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);

    uv *= rot(t  * .5);

    vec2 m = (iMouse.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);
    vec3 ro = vec3(
        m.x * .0,
        m.y * .0 + 0.,
        -.1
    );

    // ro.xy *= rot(t * .5);
    // ro.xz *= rot(t * -.01);
    // ro.yz *= rot(t * .01);


    vec3 rd = getRayDir(uv, ro, vec3(0.),1.4);

    vec3 emission = vec3(0.);

    vec2 result = raymarch(ro, rd, 1., emission);
    float dist = result.x;
    float mat = result.y;

    vec3 col = BG_COLOR;

    if(dist < MAX_DIST) {    
        vec3 p = ro + rd * dist;
        // vec3 l = normalize(vec3(1., 1., -1.));
        vec3 n = getNormal(p);    
        vec3 r = reflect(rd, n);

        Geometry geometry;
        geometry.position = p;
        geometry.normal = n;
        geometry.viewDir = normalize(ro - p);

        Material material;
        material.diffuseColor = mix(ALBEDO, vec3(0.), METALLIC);
        material.specularColor = mix(vec3(.04), ALBEDO, METALLIC);
        material.specularRoughness = ROUGHNESS;

        col = lighting(geometry, material).xyz * 4.; // cheap gain
    }

    col += emission * EMISSION;

    col *= exp(dist * -.15);

    col = pow(col, vec3(.4545));

    col *= 1. - smoothstep(1.2, 2.2, length(uv));

    fragColor = vec4(col, 1.);
}
